import copy


def _parse_path(path):
    """Parse a JSON Pointer path restricted to a single top-level key.

    Returns the decoded key string. Raises ValueError on invalid input.
    """
    if not isinstance(path, str):
        raise ValueError("path must be a string")
    if not path.startswith("/"):
        raise ValueError(f"path must begin with '/': {path!r}")

    encoded = path[1:]

    # A raw '/' in the encoded portion means multiple segments (nested).
    if "/" in encoded:
        raise ValueError(f"nested paths are not supported: {path!r}")

    # Decode ~0 and ~1; reject any other ~ escape.
    decoded = []
    i = 0
    n = len(encoded)
    while i < n:
        ch = encoded[i]
        if ch == "~":
            if i + 1 >= n:
                raise ValueError(f"invalid escape at end of path: {path!r}")
            esc = encoded[i + 1]
            if esc == "0":
                decoded.append("~")
            elif esc == "1":
                decoded.append("/")
            else:
                raise ValueError(
                    f"invalid escape '~{esc}' in path: {path!r}"
                )
            i += 2
        else:
            decoded.append(ch)
            i += 1

    return "".join(decoded)


