def dependency_levels(graph):
    if not graph:
        return []

    # Collect all task names (keys + prerequisite-only names)
    all_tasks = set(graph.keys())
    for prereqs in graph.values():
        for p in prereqs:
            all_tasks.add(p)

    # Build deduplicated prerequisite sets (no mutation of input)
    prereqs = {}
    for task in all_tasks:
        prereqs[task] = set(graph[task]) if task in graph else set()

    # Build reverse adjacency (task -> tasks that depend on it)
    dependents = {task: set() for task in all_tasks}
    for task in all_tasks:
        for p in prereqs[task]:
            dependents[p].add(task)

    # Pending prerequisite counts
    pending = {task: len(prereqs[task]) for task in all_tasks}

    # Level-based Kahn's algorithm
    current_level = sorted(task for task in all_tasks if pending[task] == 0)
    levels = []
    processed = set()

    while current_level:
        levels.append(current_level)
        processed.update(current_level)
        next_level = set()
        for task in current_level:
            for dep in dependents[task]:
                pending[dep] -= 1
                if pending[dep] == 0:
                    next_level.add(dep)
        current_level = sorted(next_level)

    if len(processed) != len(all_tasks):
        raise ValueError("Cycle detected in dependency graph")

    return levels
